import{_ as a,a as s,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第二册：实践与进步 · 单元 2 复习与自测 · 第34–42课","description":"L25–L48 原创练习和答案解析。","frontmatter":{"title":"第二册：实践与进步 · 单元 2 复习与自测 · 第34–42课","description":"L25–L48 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-2/unit-02/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 2 复习与自测","summary":"L25–L48 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 2 复习与自测 · 第25–33课","link":"/life/english/new-concept/book-2/unit-02/review-part-01"},"next":{"text":"第二册：实践与进步 · 单元 2 复习与自测 · 第43–48课","link":"/life/english/new-concept/book-2/unit-02/review-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 2 复习与自测 · 第25–33课","link":"/life/english/new-concept/book-2/unit-02/review-part-01"},"next":{"text":"第二册：实践与进步 · 单元 2 复习与自测 · 第43–48课","link":"/life/english/new-concept/book-2/unit-02/review-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/review-part-02.md","filePath":"life/english/new-concept/book-2/unit-02/review-part-02.md"}'),n={name:"life/english/new-concept/book-2/unit-02/review-part-02.md"};function l(i,e,r,h,d,p){return s(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-单元-2-复习与自测-·-第34–42课" tabindex="-1">第二册：实践与进步 · 单元 2 复习与自测 · 第34–42课 <a class="header-anchor" href="#第二册-实践与进步-·-单元-2-复习与自测-·-第34–42课" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 2 复习与自测 · 第34–42课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-02/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-34-·-间接引语与视角转换" tabindex="-1">Lesson 34 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-34-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 34 · 间接引语与视角转换 {#lesson-34-·-间接引语与视角转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The police told me that my bicycle had been found.</p><h3 id="练习-1-9" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-9" aria-label="Permalink to &quot;练习 1 {#练习-1-9}&quot;">​</a></h3><p>填 been/being：My bicycle had ___ found.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 过去完成时被动为 had been done。</p></details><p><strong>表达迁移：</strong> 写一条失物找回通知，说明报失时间、通知内容和当前状态。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The police told me that my bicycle had been found. I had reported it missing two years earlier. Its bell was gone, but the frame was undamaged.</p><p>第一句的组织方式：told me 引出接收信息的人；had been found 是从通知时刻回看更早找回动作的被动结构。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：police 通常作复数集合名词：The police are investigating，不用 is。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-034">回看本课</a></p><h2 id="lesson-35-·-不定式与目的" tabindex="-1">Lesson 35 · 不定式与目的 <a class="header-anchor" href="#lesson-35-·-不定式与目的" aria-label="Permalink to &quot;Lesson 35 · 不定式与目的 {#lesson-35-·-不定式与目的}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A cyclist stopped to help the shop assistant.</p><h3 id="练习-1-10" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-10" aria-label="Permalink to &quot;练习 1 {#练习-1-10}&quot;">​</a></h3><p>选 to help/helping：She stopped her journey ___ the assistant.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to help</p><p><strong>解析：</strong> 停止行程的目的是帮助，使用目的不定式。</p></details><p><strong>表达迁移：</strong> 写三句街头事件说明，分清看到的事实和每个人采取的行动。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A cyclist stopped to help the shop assistant. The thief dropped a bag near the door. A witness called the police instead of joining the chase.</p><p>第一句的组织方式：stopped 是主线过去动作，to help 是目的状语，the shop assistant 为 help 的宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：stop to run 是停下别的事去跑；stop running 是不再跑。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-035">回看本课</a></p><h2 id="lesson-36-·-将来进行时与过程" tabindex="-1">Lesson 36 · 将来进行时与过程 <a class="header-anchor" href="#lesson-36-·-将来进行时与过程" aria-label="Permalink to &quot;Lesson 36 · 将来进行时与过程 {#lesson-36-·-将来进行时与过程}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> At noon tomorrow, Ava will be swimming near the eastern coast.</p><h3 id="练习-1-11" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-11" aria-label="Permalink to &quot;练习 1 {#练习-1-11}&quot;">​</a></h3><p>填 swim 的形式：Ava will be ___ at noon.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> swimming</p><p><strong>解析：</strong> 进行时用 -ing，swim 双写 m。</p></details><p><strong>表达迁移：</strong> 为一次长距离活动写时间计划，包括陪同者和停止条件。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>At noon tomorrow, Ava will be swimming near the eastern coast. Her coach will follow in a boat. They will stop if the weather becomes dangerous.</p><p>第一句的组织方式：will be swimming 是将来进行时，At noon tomorrow 给出参照时点，near 表示附近而非已经上岸。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：will be swum 是被动形式，不表示她自己正在游；此处用 swimming。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-036">回看本课</a></p><h2 id="lesson-37-·-被动语态与信息重点" tabindex="-1">Lesson 37 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-37-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 37 · 被动语态与信息重点 {#lesson-37-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The new stadium will be opened in September.</p><h3 id="练习-1-12" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-12" aria-label="Permalink to &quot;练习 1 {#练习-1-12}&quot;">​</a></h3><p>补全：The stadium will ___ opened in September.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> be</p><p><strong>解析：</strong> will 后用 be 原形，再加过去分词 opened。</p></details><p><strong>表达迁移：</strong> 写三句设施进度公告，分别写当前测试、开放月份和首场活动。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The new stadium will be opened in September. Workers are testing the lights this week. The first event will take place in October.</p><p>第一句的组织方式：stadium 是被开放的设施，will be opened 为将来被动，in September 表月份。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：The event will be taken place 错误；take place 本身是不及物表达。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-037">回看本课</a></p><h2 id="lesson-38-·-过去完成时与先后关系" tabindex="-1">Lesson 38 · 过去完成时与先后关系 <a class="header-anchor" href="#lesson-38-·-过去完成时与先后关系" aria-label="Permalink to &quot;Lesson 38 · 过去完成时与先后关系 {#lesson-38-·-过去完成时与先后关系}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Before he moved north, Joel had dreamed of a quiet village.</p><h3 id="练习-1-13" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-13" aria-label="Permalink to &quot;练习 1 {#练习-1-13}&quot;">​</a></h3><p>填介词：He dreamed ___ living in a village.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> of</p><p><strong>解析：</strong> dream of 是固定搭配，of 后接动名词。</p></details><p><strong>表达迁移：</strong> 写一个理想生活与现实差异的小段落，最后给出调整办法。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Before he moved north, Joel had dreamed of a quiet village. The village was peaceful, but the winters were long. He bought warmer clothes instead of moving again.</p><p>第一句的组织方式：Before 从句 moved 给出过去参照，had dreamed 回顾更早的愿望；dream of 后接名词短语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：dream of live 错误，介词 of 后若接动词应为 living。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-038">回看本课</a></p><h2 id="lesson-39-·-间接引语与视角转换" tabindex="-1">Lesson 39 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-39-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 39 · 间接引语与视角转换 {#lesson-39-·-间接引语与视角转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Evan asked the nurse whether he could leave that afternoon.</p><h3 id="练习-1-14" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-14" aria-label="Permalink to &quot;练习 1 {#练习-1-14}&quot;">​</a></h3><p>选 if/that：He asked ___ he could leave.（是否）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> if</p><p><strong>解析：</strong> 转述是否疑问可用 if 或 whether。</p></details><p><strong>表达迁移：</strong> 转述一次预约或许可询问，包含问题、回应和等待的行动。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Evan asked the nurse whether he could leave that afternoon. The nurse said the doctor would check him first. Evan waited in his room.</p><p>第一句的组织方式：whether 引出是否问题，he could leave 为陈述语序；that afternoon 从转述者的视角定位时间。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：asked whether could he leave 保留了直接问句倒装，应改为 whether he could leave。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-039">回看本课</a></p><h2 id="lesson-40-·-非真实条件句" tabindex="-1">Lesson 40 · 非真实条件句 <a class="header-anchor" href="#lesson-40-·-非真实条件句" aria-label="Permalink to &quot;Lesson 40 · 非真实条件句 {#lesson-40-·-非真实条件句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If I knew more about her work, I would ask better questions.</p><h3 id="练习-1-15" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-15" aria-label="Permalink to &quot;练习 1 {#练习-1-15}&quot;">​</a></h3><p>填 know：If I ___ more, I would ask better questions.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> knew</p><p><strong>解析：</strong> 当前非真实假设的 if 从句用过去式。</p></details><p><strong>表达迁移：</strong> 写三句宴会交流反思，用一个假设句说明可以怎样改善提问。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>If I knew more about her work, I would ask better questions. Instead, I asked about the meal. She smiled and recommended a local restaurant.</p><p>第一句的组织方式：knew 表非真实现在假设，would ask 表假设结果；better 是 good 的比较级。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：If I would know 通常不能表达这种标准假设；用 If I knew。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-040">回看本课</a></p><h2 id="lesson-41-·-情态动词的意义与形式" tabindex="-1">Lesson 41 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-41-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 41 · 情态动词的意义与形式 {#lesson-41-·-情态动词的意义与形式}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> You need not buy the hat just because it is fashionable.</p><h3 id="练习-1-16" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-16" aria-label="Permalink to &quot;练习 1 {#练习-1-16}&quot;">​</a></h3><p>将“不必买”补全：You do not need ___ buy it.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> 实义动词 need 的否定结构后接 to 不定式。</p></details><p><strong>表达迁移：</strong> 写三句购物建议，区分无需做的事与值得尝试的事。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>You need not buy the hat just because it is fashionable. Try it on in front of the mirror. Choose the one that feels comfortable.</p><p>第一句的组织方式：need not 在此是情态用法，后接 buy 原形；because 从句说明不应成为唯一理由的因素。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：need not buy 是不必买，不能译成“不准买”；do not need to buy 也是不必买。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-041">回看本课</a></p><h2 id="lesson-42-·-动词、宾语与补足语" tabindex="-1">Lesson 42 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-42-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 42 · 动词、宾语与补足语 {#lesson-42-·-动词、宾语与补足语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We watched the bird move towards the musician&#39;s hand.</p><h3 id="练习-1-17" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-17" aria-label="Permalink to &quot;练习 1 {#练习-1-17}&quot;">​</a></h3><p>选择 move/to move：We watched the bird ___ towards the hand.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> move</p><p><strong>解析：</strong> 感官动词 watch 后宾语加不带 to 的原形。</p></details><p><strong>表达迁移：</strong> 描述一个动物反应，分别写观察到的动作和仍不能确定的原因。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We watched the bird move towards the musician&#39;s hand. The music stopped, but the hand kept moving. The bird continued to follow it.</p><p>第一句的组织方式：watched 后接宾语 the bird，再接原形 move 作宾语补足语；towards 标记方向。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：watched the bird to move 不合此感官动词结构；主动式通常省略 to。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-042">回看本课</a></p>',76)])])}const u=a(n,[["render",l]]);export{m as __pageData,u as default};
